INSERT INTO products(category_id, name, description, calories_per_100g,
                     protein_per_100g, fat_per_100g, carbs_per_100g,
                     shopping_name, edible_yield)
SELECT category.id, seed.name, seed.description, seed.calories,
       seed.protein, seed.fat, seed.carbs, seed.shopping_name, seed.edible_yield
FROM seed
JOIN product_categories category ON category.code = seed.category_code
WHERE NOT EXISTS (
    SELECT 1
    FROM products existing
    WHERE lower(btrim(existing.name)) = lower(btrim(seed.name))
);
